18. package de.dominikschadow.javasecurity.hash;
19. 
20. import org.apache.shiro.crypto.hash.DefaultHashService;
21. import org.apache.shiro.crypto.hash.Hash;
22. import org.apache.shiro.crypto.hash.HashRequest;
23. import org.apache.shiro.lang.util.ByteSource;
24. 
25. import java.util.Arrays;
26. 
27. /**
28.  * SHA512 hashing sample with Apache Shiro. Uses a private base salt, configures the number of iterations, automatically
29.  * generates a salt and calculates the hash value.
30.  *
31.  * @author Dominik Schadow
32.  */
33. public class SHA512 {
34.     /**
35.      * Nothing up my sleeve number as private salt, not good for production.
36.      */
37.     private static final byte[] PRIVATE_SALT_BYTES = {3, 1, 4, 1, 5, 9, 2, 6, 5};
38.     private static final int ITERATIONS = 1000000;
39. 
40.     public Hash calculateHash(String password) {
41.         DefaultHashService hashService = new DefaultHashService();
42.         hashService.setDefaultAlgorithmName("SHA-512");
43. 
44.         HashRequest hashRequest = new HashRequest.Builder()
45.                 .setSource(ByteSource.Util.bytes(password))
46.                 .setAlgorithmName("SHA-512")
47.                 .addParameter("SimpleHash.iterations", ITERATIONS)
48.                 .addParameter("SimpleHash.secretSalt", java.util.Base64.getEncoder().encodeToString(PRIVATE_SALT_BYTES))
49.                 .build();
50. 
51.         return hashService.computeHash(hashRequest);
52.     }
53. 
54.     public boolean verifyPassword(byte[] originalHash, ByteSource publicSalt, String password) {
55.         DefaultHashService hashService = new DefaultHashService();
56.         hashService.setDefaultAlgorithmName("SHA-512");
57. 
58.         HashRequest hashRequest = new HashRequest.Builder()
59.                 .setSource(ByteSource.Util.bytes(password))
60.                 .setSalt(publicSalt)
61.                 .setAlgorithmName("SHA-512")
62.                 .addParameter("SimpleHash.iterations", ITERATIONS)
63.                 .addParameter("SimpleHash.secretSalt", java.util.Base64.getEncoder().encodeToString(PRIVATE_SALT_BYTES))
64.                 .build();
65. 
66.         Hash comparisonHash = hashService.computeHash(hashRequest);
67. 
68.         return Arrays.equals(originalHash, comparisonHash.getBytes());
69.     }
70. }
